- 		if (acrtc->wb_pending) {
- 			job = list_first_entry_or_null(&acrtc->wb_conn->job_queue,
- 						       struct drm_writeback_job,
- 						       list_entry);
- 			acrtc->wb_pending = false;
- 			spin_unlock_irqrestore(&acrtc->wb_conn->job_lock, flags);
