- 		int_params.int_context = INTERRUPT_HIGH_IRQ_CONTEXT;
- 		int_params.irq_source =
- 			dc_interrupt_to_irq_source(dc, i, 0);
- 
- 		if (int_params.irq_source == DC_IRQ_SOURCE_INVALID ||
- 			int_params.irq_source  < DC_IRQ_SOURCE_PFLIP_FIRST ||
