- 			dm_new_state->abm_sysfs_forbidden = false;
- 			break;
- 		case ABM_LEVEL_OFF:
- 			dm_new_state->abm_sysfs_forbidden = true;
- 			dm_new_state->abm_level = ABM_LEVEL_IMMEDIATE_DISABLE;
