- 		ABM_LEVEL_IMMEDIATE_DISABLE ? 0 :
- 		to_dm_connector_state(connector->state)->abm_level;
- 	drm_modeset_unlock(&dev->mode_config.connection_mutex);
- 
- 	return sysfs_emit(buf, "%u\n", val);
