- 			dc_sink_release(aconnector->hdmi_prev_sink);
- 			aconnector->hdmi_prev_sink = NULL;
- 		}
- 	}
- 
- 	if (aconnector->bl_idx != -1) {
- 		backlight_device_unregister(dm->backlight_dev[aconnector->bl_idx]);
- 		dm->backlight_dev[aconnector->bl_idx] = NULL;
