- static int fill_hdr_info_packet(const struct drm_connector_state *state,
- 				struct dc_info_packet *out)
- {
- 	struct hdmi_drm_infoframe frame;
- 	unsigned char buf[30]; /* 26 + 4 */
- 	ssize_t len;
- 	int ret, i;
- 
- 	memset(out, 0, sizeof(*out));
- 
